<template>
  <div class="test-img-compress">
    <div class="original-img"  @click="getBase64Img">
      {{ base64ImgSize }}
      <img :src="base64Img" />
    </div>

    <div class="after-compress" @click="compressImg">
      {{  afterCompressImgSize }}
      <img :src="afterImg" />
    </div>
  </div>
</template>
<script>
import { getBase64ImgSize, compressImgBySize } from '../../Utils/processImg';

export default {
  name: 'TestCompress',
  data() {
    return {
      afterCompressImgSize: '',
      afterImg: '',
      base64ImgSize: 0,
      base64Img: 'data:image/png;base64,',
    };
  },
  methods: {
    getBase64Img() {
      this.base64ImgSize = getBase64ImgSize(this.base64Img);
    },
    compressImg() {
      // @ts-ignore
      compressImgBySize(this.base64Img, 500).then((baseImg) => {
        console.log('== test get compress img', baseImg);
        this.afterImg = baseImg;
        // @ts-ignore
        this.afterCompressImgSize = getBase64ImgSize(this.afterImg);
      }).catch((err) => {
        console.log('=== test compress error', err);
      });
    },
  },
};
</script>
<style lang="scss" scoped src="./TestCompress.scss"></style>
